import{_ as l,a0 as r,w as p,s as d,ao as o,I as n,x as s,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何知道你是否使用了代理服務器？ | LCTT x X-CMD","titleTemplate":false,"description":"如何知道你是否使用了代理服務器？ | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何知道你是否使用了代理服務器？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何知道你是否使用了代理服務器？ | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230315.1 ⭐️ How to know if You are Behind a Proxy Server","title":"如何知道你是否使用了代理服務器？","tag":"202303","desc":""},"relativePath":"202303/20230315.1 ⭐️ How to know if You are Behind a Proxy Server.md","filePath":"[post].md"}'),h={name:"202303/20230315.1 ⭐️ How to know if You are Behind a Proxy Server.md"};function g(u,t,c,k,b,m){const e=r("Link");return p(),d("div",null,[t[18]||(t[18]=o('<h1 id="如何知道你是否使用了代理服務器" tabindex="-1">如何知道你是否使用了代理服務器？ <a class="header-anchor" href="#如何知道你是否使用了代理服務器" aria-label="Permalink to “如何知道你是否使用了代理服務器？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/24/174021wkdzn81kvtnngzaw.jpg" alt=""></p><p>什麼是代理？</p><p>代理是充當客户端和另一台服務器之間的中介的服務器或軟件應用。它充當客户端和互聯網之間的網關，允許用户訪問在線資源，同時隱藏他們的身份、位置和其他個人信息。</p><p>代理通常用於增強安全性和隱私，併為你的網絡添加過濾器/防火牆。</p><p>有幾種類型的代理，如 HTTP 代理、SOCKS 代理、透明代理等。</p><p>除非你在透明代理後面，否則檢查起來毫不費力。在這裏，我將討論檢測透明代理和常用代理的方法。</p><h3 id="如何檢查你是否在透明代理後面" tabindex="-1">如何檢查你是否在透明代理後面 <a class="header-anchor" href="#如何檢查你是否在透明代理後面" aria-label="Permalink to “如何檢查你是否在透明代理後面”">​</a></h3><p>雖然每種類型的代理都有其特性和功能，但如果它是透明代理，你將無法在客户端的 PC 上檢測到它。這是因為透明代理在後台靜默運行，攔截所有流量而不修改它。</p><p>有時，可能是你的互聯網服務提供商和內容交付網絡使用它們來緩存資源的副本以節省帶寬或只是為了監視/過濾網絡。</p><p>有幾種方法可以檢查你是否在透明代理後面：</p><ul><li><strong>通過某些在線 IP 檢測/檢查網站獲得的 IP 地址可能與你的計算機或設備的 IP 地址不匹配</strong>。因為代理服務器正在攔截你的流量並將其與 IP 地址一起發送出去。</li><li><strong>檢查你的網絡設置以查看是否配置了代理服務器。</strong></li><li><strong>藉助一些在線代理檢測工具。</strong></li><li><strong>連接到你知道不存在的服務器。</strong> 如果網頁上顯示的錯誤看起來與平時不同，你可能使用了代理。</li></ul>',12)),n("p",null,[t[1]||(t[1]=s("無論你喜歡與否，你始終可以使用 ",-1)),i(e,{href:"https://itsfoss.com/best-vpn-linux/"},{default:a(()=>[...t[0]||(t[0]=[s("VPN 服務",-1)])]),_:1}),t[2]||(t[2]=s(" 繞過透明代理。",-1))]),t[19]||(t[19]=o('<h3 id="如何檢查你是否在-ubuntu-上使用代理" tabindex="-1">如何檢查你是否在 Ubuntu 上使用代理 <a class="header-anchor" href="#如何檢查你是否在-ubuntu-上使用代理" aria-label="Permalink to “如何檢查你是否在 Ubuntu 上使用代理”">​</a></h3><p>Ubuntu 或任何其他 Linux 發行版提供了多種檢查方法。此處使用運行 GNOME 的 Ubuntu 22.10。</p><h4 id="使用-gnome-設置" tabindex="-1">使用 GNOME 設置 <a class="header-anchor" href="#使用-gnome-設置" aria-label="Permalink to “使用 GNOME 設置”">​</a></h4><p>這是直接的 GUI 方式。打開 GNOME <ruby>設置<rt>Settings</rt></ruby> 並轉到 “<ruby>網絡<rt>Networks</rt></ruby>” 選項卡，然後按旁邊的齒輪圖標。</p><p><img src="https://itsfoss.com/content/images/2023/02/select-the-gear-icon-adjacent-to-proxy.png" alt="Select the gear icon adjacent to the Network proxy section"></p><p>它應該默認 <ruby>禁用<rt>Disabled</rt></ruby>。</p><p>如果你在代理後面，你可以在這裏看到不同的狀態。在代理設置中，你可以看到，我在這裏使用了代理（手動配置）。</p><p><img src="https://itsfoss.com/content/images/2023/02/Proxy-in-GNOME-settings.png" alt="Proxy details in GNOME Settings"></p><p>可以使用 GNOME 桌面中的 <code>gsettings</code> 命令更改相同的代理狀態。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.system.proxy mode &#39;none&#39;</span></span></code></pre></div><p>你可以將 <code>none</code> 替換為 <code>auto</code> 或 <code>manual</code>。請記住，此設置是臨時的，僅適用於當前用户。</p><h4 id="使用命令列" tabindex="-1">使用命令列 <a class="header-anchor" href="#使用命令列" aria-label="Permalink to “使用命令列”">​</a></h4><p>你可以通過命令列以多種方式獲取代理的狀態。</p><h5 id="通過列出關聯的環境變量獲取代理的狀態" tabindex="-1">通過列出關聯的環境變量獲取代理的狀態 <a class="header-anchor" href="#通過列出關聯的環境變量獲取代理的狀態" aria-label="Permalink to “通過列出關聯的環境變量獲取代理的狀態”">​</a></h5><p>打開終端並運行以下任一命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>env | grep -i proxy</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/environment | grep -i proxy</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set | grep -i proxy</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/set_grep_proxy.png" alt="Using set command to check Proxy variables"></p><p>空輸出意味着沒有配置代理。否則，它將打印相關的環境變量。</p><blockquote><p>🚧 請注意，如果你將代理設置為環境變量，這將起作用。</p></blockquote><p>或者，你可以回顯每個代理變量以檢查是否設置了特定的代理變量。</p><p>以下是你可以在終端中輸入的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo $http_proxy</span></span></code></pre></div><h5 id="使用-nmcli-命令檢查" tabindex="-1">使用 nmcli 命令檢查 <a class="header-anchor" href="#使用-nmcli-命令檢查" aria-label="Permalink to “使用 nmcli 命令檢查”">​</a></h5><p>打開終端並輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli connection show</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/nmcli-connection-show.png" alt="List all the connections using nmcli command"></p><p>這將列出你的連接和關聯的 UUID 編號。記下要檢查的連接的 UUID 編號。然後使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nmcli connection show &lt;UUID or name&gt; | grep -i &quot;proxy&quot;</span></span></code></pre></div><p>這將列出變量，你可以在其中記下代理服務器和端口。</p><p><img src="https://itsfoss.com/content/images/2023/02/proxy-using-nmcli.png" alt="Proxy details using nmcli command"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我希望本指南可以幫助你瞭解你是否在使用代理。</p><p>我必須提一下，<strong>並非所有代理配置都是惡意的。</strong></p><p>但是，瞭解你的系統是否配置了代理很重要。</p><hr>',37)),n("p",null,[t[4]||(t[4]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/check-proxy-server/"},{default:a(()=>[...t[3]||(t[3]=[s("https://itsfoss.com/check-proxy-server/",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sreenath/"},{default:a(()=>[...t[5]||(t[5]=[s("Sreenath",-1)])]),_:1}),t[10]||(t[10]=s(" 選題：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:a(()=>[...t[6]||(t[6]=[s("lkxed",-1)])]),_:1}),t[11]||(t[11]=s(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[7]||(t[7]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[s("Linux中國",-1)])]),_:1}),t[17]||(t[17]=s(" 榮譽推出",-1))])])}const C=l(h,[["render",g]]);export{y as __pageData,C as default};
